sys_ws_operation.operation_script:
(function process(request, response) {

    try {

        // =====================================================
        // SECURITY
        // =====================================================
        if (
            !gs.hasRole(
                'x_1760545_smarta_0.smartattend_manager'
            )
        ) {

            response.setStatus(403);

            response.setBody({
                success: false,
                message: 'Manager access is required.'
            });

            return;
        }


        var managerId =
            gs.getUserID();


        // =====================================================
        // REQUEST BODY
        // =====================================================
        var body =
            request.body.data || {};


        var profileId =
            String(
                body.profile_id || ''
            ).trim();


        var shiftId =
            String(
                body.shift_id || ''
            ).trim();


        if (!profileId) {

            returnError(
                400,
                'Employee profile is required.'
            );

            return;
        }


        if (!shiftId) {

            returnError(
                400,
                'Shift is required.'
            );

            return;
        }


        // =====================================================
        // VALIDATE EMPLOYEE BELONGS TO MANAGER
        // =====================================================
        var profile =
            new GlideRecord(
                'x_1760545_smarta_0_employee_profile'
            );


        if (
            !profile.get(
                profileId
            )
        ) {

            returnError(
                404,
                'Employee profile was not found.'
            );

            return;
        }


        if (
            profile.getValue(
                'manager'
            ) !== managerId
        ) {

            returnError(
                403,
                'You can assign shifts only to employees assigned to you.'
            );

            return;
        }


        if (
            profile.getValue(
                'active'
            ) !== '1'
        ) {

            returnError(
                400,
                'Employee profile is inactive.'
            );

            return;
        }


        // =====================================================
        // VALIDATE SHIFT
        // =====================================================
        var shift =
            new GlideRecord(
                'x_1760545_smarta_0_shift'
            );


        if (
            !shift.get(
                shiftId
            )
        ) {

            returnError(
                404,
                'Shift was not found.'
            );

            return;
        }


        if (
            shift.getValue(
                'active'
            ) !== '1'
        ) {

            returnError(
                400,
                'Selected shift is inactive.'
            );

            return;
        }


        // =====================================================
        // CURRENT SHIFT
        // =====================================================
        var oldShiftId =
            profile.getValue(
                'shift'
            ) || '';


        var oldShiftName =
            'Not Assigned';


        if (oldShiftId) {

            oldShiftName =
                profile.shift
                    .getDisplayValue() ||
                'Not Assigned';

        }


        // =====================================================
        // UPDATE PROFILE
        // =====================================================
        profile.setValue(
            'shift',
            shiftId
        );


        var updatedId =
            profile.update();


        if (!updatedId) {

            returnError(
                500,
                'Unable to assign shift.'
            );

            return;
        }


        // =====================================================
        // RESPONSE
        // =====================================================
        response.setStatus(200);

        response.setBody({

            success: true,

            message:
                'Shift assigned successfully.',

            employee: {

                profile_id:
                    profile.getUniqueValue(),

                employee_id:
                    profile.getValue(
                        'employee'
                    ),

                employee:
                    profile.employee
                        .getDisplayValue(),

                previous_shift:
                    oldShiftName,

                current_shift:
                    shift.getValue(
                        'shift_name'
                    ) ||
                    shift.getDisplayValue(),

                current_shift_id:
                    shift.getUniqueValue()

            }

        });


        // =====================================================
        // HELPER
        // =====================================================
        function returnError(
            status,
            message
        ) {

            response.setStatus(
                status
            );

            response.setBody({
                success: false,
                message: message
            });

        }


    }
    catch (e) {

        gs.error(
            '[SmartAttend Assign Shift] ' +
            e.message
        );


        response.setStatus(500);

        response.setBody({

            success: false,

            message:
                'Unable to assign shift.'

        });

    }

})(request, response);
